using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterLevelTable", menuName = "Data/CharacterLevelTable")]
public class CharacterLevelTable : ScriptableObject
{
	[Header("XPs")]
	[SerializeField]
	private int[] levelXP;

	[Header("Assets")]
	[SerializeField]
	private SaveSystem saveSystem;

	public int[] LevelXP => levelXP;

	public int GetCharacterCurrentLevelXP(int characterLevel, int characterXP)
	{
		if (characterLevel < levelXP.Length)
		{
			for (int i = 0; i < characterLevel; i++)
			{
				characterXP -= levelXP[i];
			}
			return characterXP;
		}
		return -1;
	}

	public int GetCharacterNextLevelXP(int characterLevel)
	{
		if (characterLevel < levelXP.Length)
		{
			return levelXP[characterLevel];
		}
		return -1;
	}

	public int GetCharacterLevel(Character character)
	{
		int num = character.CharacterProgression.CharacterXP;
		for (int i = 0; i < levelXP.Length; i++)
		{
			if (num < levelXP[i])
			{
				return i;
			}
			num -= levelXP[i];
		}
		return 6;
	}

	public int GetXPSumAmount()
	{
		int num = 0;
		for (int i = 0; i < levelXP.Length; i++)
		{
			num += levelXP[i];
		}
		return num;
	}
}
